// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        address actor
    ) public {
        vm.prank(actor);
        try c.setL1BlockValues(
            _number, _timestamp, _basefee, _hash,
            _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
        ) {
            // General rule: setL1BlockValues must never modify stored state,
            // so l1FeeScalar() must always remain 0 after any call.
            assertTrue(c.l1FeeScalar() == 0);
        } catch {
            // Reverting (unauthorized caller) trivially satisfies the rule.
            assertTrue(c.l1FeeScalar() == 0);
        }
    }
}
